import{_ as c,o as d,c as o,a3 as a}from"./chunks/framework.BZCmpA0A.js";const u=JSON.parse('{"title":"Spec 19：工作目錄與命令處理","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-19-cwd-shell.md","filePath":"SPEC-19-cwd-shell.md","lastUpdated":1793166439000}'),t={name:"SPEC-19-cwd-shell.md"};function l(r,e,s,h,i,n){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="spec-19-工作目錄與命令處理" tabindex="-1">Spec 19：工作目錄與命令處理 <a class="header-anchor" href="#spec-19-工作目錄與命令處理" aria-label="Permalink to &quot;Spec 19：工作目錄與命令處理&quot;">​</a></h1><h2 id="目標與範圍" tabindex="-1">目標與範圍 <a class="header-anchor" href="#目標與範圍" aria-label="Permalink to &quot;目標與範圍&quot;">​</a></h2><p>讓使用者在 WUWAOS 的 shell 使用 <code>cd</code> 系列與 <code>pwd</code>，並理解命令如何進入核心。既有檔案命令和 fan 支援相對與絕對路徑，更新主題文件與網站；不新增測試程式碼。</p><h2 id="設計" tabindex="-1">設計 <a class="header-anchor" href="#設計" aria-label="Permalink to &quot;設計&quot;">​</a></h2><p>每個 PCB（行程控制區塊）持有目前及上一次工作目錄，初始 shell 從 <code>/</code> 開始。spawn、fork 與 pipe 子行程複製父目錄，exec 保留。目錄改變只影響該行程；不是全系統共用目錄。<code>cd</code> 與 <code>cd ~</code> 指向 <code>/home/user</code>，<code>cd ~/path</code> 由 shell 展開，<code>cd -</code> 回前一個目錄並顯示結果；<code>pwd</code> 顯示目前目錄。目錄不存在或不是目錄時保留原設定。</p><p>核心新增 chdir 與 getcwd 系統呼叫，檔案及 fan 執行呼叫將相對路徑接上呼叫行程的目錄，保留 <code>.</code>、<code>..</code> 讓 WUFS 逐層查找。<code>cd</code> 成功查找並確認是目錄後才正規化儲存路徑，避免 <code>missing/..</code> 錯誤通過。<code>ls</code> 無參數列出目前目錄。絕對路徑仍從根目錄查找。完整合併後路徑最多 127 bytes；shell 無引號或含空白路徑解析。</p><h2 id="步驟與驗收條件" tabindex="-1">步驟與驗收條件 <a class="header-anchor" href="#步驟與驗收條件" aria-label="Permalink to &quot;步驟與驗收條件&quot;">​</a></h2><ol><li>更新 PCB、路徑合併與目錄檢查，提供使用者 syscall。</li><li>加入 shell 命令，更新 help、程式碼導覽、主題網站與 README。</li><li>建置後以獨立磁碟在 QEMU 操作，檢查 <code>pwd</code>、<code>cd</code>、<code>cd ..</code>、<code>cd -</code>、<code>cd ~/path</code>、相對檔案操作、不存在及非目錄錯誤、子行程繼承及 exec、fan 保存與重啟後檔案保留；原磁碟不被驗證操作修改。</li></ol><h2 id="驗收紀錄" tabindex="-1">驗收紀錄 <a class="header-anchor" href="#驗收紀錄" aria-label="Permalink to &quot;驗收紀錄&quot;">​</a></h2><p>Clang 建置通過；使用獨立 WUFS 與 swap 磁碟在 QEMU 互動確認上述目錄切換、錯誤保留目錄、mkdir/touch/write/cp/ls/cat/rm、spawn 的 PCB、fork/exec 的 counter PCB、fan 相對路徑保存及重新啟動後讀回；亦確認原本的 writer | reader 可運作。新 shell 重啟從 <code>/</code> 開始。尚未逐一涵蓋所有長路徑邊界與所有終端。</p><p>參考使用者筆記 <code>notes/Chapter 13 file system Interface.md</code> 中的目錄與路徑觀念；此處敘述的是 WUWAOS 自己的簡化實作，不宣稱 Linux 相容。</p><h2 id="提示字元更新" tabindex="-1">提示字元更新 <a class="header-anchor" href="#提示字元更新" aria-label="Permalink to &quot;提示字元更新&quot;">​</a></h2><p>shell 每次等待命令前讀取目前工作目錄：根目錄顯示 <code>wuwaos/&gt;</code>，<code>/note</code> 顯示 <code>wuwaos/note&gt;</code>；讀取失敗則顯示 <code>wuwaos?&gt;</code>。切換成功或失敗後提示字元應反映行程實際位置。</p><p>驗證：使用獨立磁碟在 QEMU 確認根目錄、<code>cd note</code>、切換失敗、<code>cd ..</code>、<code>cd</code> 與 <code>cd -</code> 的提示字元。</p>',14)])])}const f=c(t,[["render",l]]);export{u as __pageData,f as default};
